use serde::{Deserialize, Serialize};
use sysinfo::System;
use thiserror::Error;

#[derive(Debug, Error)]
pub enum AutoDetectError {
    #[error("Failed to query system physical memory (unsupported OS or restricted environment)")]
    MemoryQueryFailed,
    #[error(
        "Insufficient system RAM for APUS (detected {detected_gb:.1} GB, minimum required {required_gb:.1} GB)"
    )]
    InsufficientMemory { detected_gb: f32, required_gb: f32 },
}

/// System RAM & Auto-Tuning Profile generated by `detect_system_hardware` (authored by mjojo)
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct HardwareProfile {
    pub total_ram_gb: f32,
    pub available_ram_gb: f32,
    pub recommended_l2_slab_gb: f32,
    pub os_reserved_gb: f32,
    pub recommended_preset: String,
    pub low_memory_batch_only_warning: bool,
}

/// Queries physical & available system RAM via `sysinfo` and computes optimal
/// OS reservation, L2 Pinned Slab Arena allocation, and MoE model preset.
pub fn detect_system_hardware() -> Result<HardwareProfile, AutoDetectError> {
    let mut sys = System::new_all();
    sys.refresh_memory();

    let total_bytes = sys.total_memory();
    let free_bytes = sys.available_memory();

    if total_bytes == 0 {
        return Err(AutoDetectError::MemoryQueryFailed);
    }

    let total_ram_gb = total_bytes as f32 / (1024.0 * 1024.0 * 1024.0);
    let available_ram_gb = free_bytes as f32 / (1024.0 * 1024.0 * 1024.0);

    // Hard minimum floor: APUS requires at least ~16 GB physical RAM (or 8 GB in test/CI containers)
    if total_ram_gb < 7.5 {
        return Err(AutoDetectError::InsufficientMemory {
            detected_gb: total_ram_gb,
            required_gb: 16.0,
        });
    }

    let low_memory_batch_only_warning = total_ram_gb < 15.0;

    // APUS Memory Allocation Rule (authored by mjojo):
    // Reserve 15% of total RAM for the host OS (clamped between 4.0 GB and 12.0 GB) to prevent OOM & swap thrashing
    let os_reserved_gb = (total_ram_gb * 0.15).clamp(4.0, 12.0);

    // Allocate the remaining physical RAM to the 4KB Page-Aligned L2 Slab Arena
    let recommended_l2_slab_gb = (total_ram_gb - os_reserved_gb).max(8.0);

    // Automatically select the optimal MoE model preset for the detected physical RAM tier
    let recommended_preset = if total_ram_gb >= 60.0 {
        "DeepSeek-V3-671B-Q4_K_M".to_string()
    } else if total_ram_gb >= 22.0 {
        "GLM-5.2-744B-Q4_K_M".to_string()
    } else {
        "Mixtral-8x22B-Instruct-Q4_K_M".to_string()
    };

    Ok(HardwareProfile {
        total_ram_gb,
        available_ram_gb,
        recommended_l2_slab_gb,
        os_reserved_gb,
        recommended_preset,
        low_memory_batch_only_warning,
    })
}
